const reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const selectionModal = document.getElementById("selection-modal");
const selectionButton = document.getElementById("selection-button");
const selectionCount = document.getElementById("selection-count");
const selectionList = document.getElementById("selection-list");
const selectionNote = document.getElementById("selection-note");
const selectionEmpty = document.getElementById("selection-empty");
const selectionWhatsappPrincipal = document.getElementById("selection-whatsapp-principal");
const selectionWhatsappSecundaria = document.getElementById("selection-whatsapp-secundaria");
const clearSelection = document.getElementById("clear-selection");

const SEDES = {
  principal: { nombre: "Kalú Accesorios", numero: "573117570138" },
  secundaria: { nombre: "Kalú Disfraces", numero: "573215055733" },
};

const waLink = (numero, mensaje) => `https://wa.me/${numero}?text=${encodeURIComponent(mensaje)}`;
const SHEET_CSV_URL = "";
const LOW_STOCK = 5;
let stock = {};
const stockOf = (code) => stock[code] || {};
const isSoldOut = (code) => stockOf(code).units === 0;
const fmtPrice = (n) => "$" + Math.round(n).toLocaleString("es-CO");

const parseCSV = (text) => {
  const rows = [];
  let row = [], cell = "", quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; }
      else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === ",") { row.push(cell); cell = ""; }
    else if (c === "\n") { row.push(cell); rows.push(row); row = []; cell = ""; }
    else if (c !== "\r") cell += c;
  }
  if (cell !== "" || row.length) { row.push(cell); rows.push(row); }
  return rows;
};

const toNumber = (v) => {
  const digits = String(v ?? "").trim().replace(/[.,]\d{1,2}$/, "").replace(/[^0-9]/g, "");
  return digits === "" ? null : parseInt(digits, 10);
};

const applyStock = () => {
  document.querySelectorAll(".card[data-code]").forEach((card) => {
    const code = card.dataset.code;
    const info = stockOf(code);
    const p = card.querySelector(".details p");
    const wrap = card.querySelector(".image-wrap");
    if (p) {
      if (!p.dataset.original) p.dataset.original = p.textContent;
      p.textContent = info.price != null ? fmtPrice(info.price) : p.dataset.original;
      p.classList.toggle("has-price", info.price != null);
    }
    if (wrap) {
      wrap.querySelectorAll(".stock-badge").forEach((b) => b.remove());
      card.classList.toggle("sold-out", info.units === 0);
      if (info.units === 0) {
        wrap.insertAdjacentHTML("beforeend", '<span class="stock-badge out">Agotado</span>');
      } else if (info.units != null && info.units <= LOW_STOCK) {
        wrap.insertAdjacentHTML("beforeend", `<span class="stock-badge">${info.units === 1 ? "Queda 1" : "Quedan " + info.units}</span>`);
      }
    }
  });
  if (typeof updateSelection === "function") updateSelection();
};

const loadStock = async () => {
  if (!SHEET_CSV_URL) return;
  try {
    const url = SHEET_CSV_URL + (SHEET_CSV_URL.includes("?") ? "&" : "?") + "t=" + Math.floor(Date.now() / 300000);
    const response = await fetch(url);
    if (!response.ok) return;
    const rows = parseCSV(await response.text());
    const norm = (t) => String(t || "").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const head = rows.shift().map(norm);
    const iCode = head.findIndex((h) => ["codigo", "code", "cod"].includes(h));
    const iPrice = head.findIndex((h) => ["precio", "price"].includes(h));
    const iUnits = head.findIndex((h) => ["unidades", "stock", "cantidad", "disponibles"].includes(h));
    if (iCode < 0) return;
    const next = {};
    rows.forEach((r) => {
      const code = (r[iCode] || "").trim();
      if (!code) return;
      next[code] = {
        price: iPrice >= 0 ? toNumber(r[iPrice]) : null,
        units: iUnits >= 0 ? toNumber(r[iUnits]) : null,
      };
    });
    stock = next;
    applyStock();
  } catch {}
};

let selectedProducts = [];
try {
  const savedSelection = JSON.parse(window.localStorage.getItem("kalu-selection"));
  if (Array.isArray(savedSelection)) selectedProducts = savedSelection;
} catch {
  selectedProducts = [];
}

const saveSelection = () => {
  try {
    window.localStorage.setItem("kalu-selection", JSON.stringify(selectedProducts));
  } catch {}
};

const isSelected = (product) => product && selectedProducts.some((item) => item.code === product.code);
const productLink = (code) => new URL(`p/${encodeURIComponent(code)}.html`, location.href).href;
const buildSelectionMessage = (products) =>
  `Hola Kalú, quiero consultar por estos productos:\n${products.map((product) => `• ${product.name} (${product.code})\n${productLink(product.code)}`).join("\n\n")}`;

const syncCardButtons = () => {
  const selectedCodes = new Set(selectedProducts.map((p) => p.code));
  document.querySelectorAll(".card[data-code]").forEach((card) => {
    const btn = card.querySelector(".mini-button");
    if (!btn) return;
    const added = selectedCodes.has(card.dataset.code);
    btn.classList.toggle("is-added", added);
    btn.textContent = added ? "✓ En mi pedido" : "+ Agregar";
  });
};

const updateSelection = () => {
  const hasProducts = selectedProducts.length > 0;
  if (selectionCount) selectionCount.textContent = selectedProducts.length;
  if (selectionButton) selectionButton.setAttribute("aria-label", `Abrir mi pedido: ${selectedProducts.length} productos`);
  if (selectionList) selectionList.hidden = !hasProducts;
  if (selectionEmpty) selectionEmpty.hidden = hasProducts;

  const esc = (value) =>
    String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  if (selectionList) {
    selectionList.innerHTML = selectedProducts
      .map(
        (product) => `
      <li class="selection-item" style="--selection-image:url('${esc(product.image || "")}')">
        <div><strong>${esc(product.name)}${isSoldOut(product.code) ? '<em class="sel-out">Agotado</em>' : ""}</strong><span>${esc(product.code)}${/^DF/.test(product.code) ? " · Alquiler" : " · Venta"}</span></div>
        <button class="remove-selection" type="button" data-remove-code="${esc(product.code)}" aria-label="Quitar ${esc(product.name)}">×</button>
      </li>
    `
      )
      .join("");
  }

  if (clearSelection) clearSelection.disabled = !hasProducts;
  if (selectionNote) selectionNote.hidden = !selectedProducts.some((product) => /^DF/.test(product.code));

  const summary = document.getElementById("selection-summary");
  const summaryCount = document.getElementById("selection-summary-count");
  if (summary) summary.hidden = !hasProducts;
  if (summaryCount) {
    summaryCount.textContent = `${selectedProducts.length} ${selectedProducts.length === 1 ? "producto seleccionado" : "productos seleccionados"}`;
  }

  const available = selectedProducts.filter((product) => !isSoldOut(product.code));
  const selectionMsg = available.length ? buildSelectionMessage(available) : "Hola Kalú, quiero consultar disponibilidad de productos.";

  if (selectionWhatsappPrincipal) {
    selectionWhatsappPrincipal.textContent = `Consultar con ${SEDES.principal.nombre}`;
    selectionWhatsappPrincipal.href = available.length ? waLink(SEDES.principal.numero, selectionMsg) : "#";
    selectionWhatsappPrincipal.setAttribute("aria-disabled", String(!available.length));
  }
  if (selectionWhatsappSecundaria) {
    selectionWhatsappSecundaria.textContent = `Consultar con ${SEDES.secundaria.nombre}`;
    selectionWhatsappSecundaria.href = available.length ? waLink(SEDES.secundaria.numero, selectionMsg) : "#";
    selectionWhatsappSecundaria.setAttribute("aria-disabled", String(!available.length));
  }

  syncCardButtons();
};

const CONFETTI_COLORS = ["#ffbd18", "#f15a0b", "#a71c65", "#74206e", "#ffffff"];
function spawnConfetti(originX, originY, container) {
  if (reduceMotion) return;
  const count = 8;
  for (let i = 0; i < count; i++) {
    const bit = document.createElement("i");
    bit.className = "confetti-bit";
    const angle = (Math.PI * 2 * i) / count + Math.random() * 0.5;
    const dist = 46 + Math.random() * 58;
    const dx = originX + Math.cos(angle) * dist;
    const dy = originY + Math.sin(angle) * dist - 18;
    bit.style.setProperty("--x0", `${originX}px`);
    bit.style.setProperty("--y0", `${originY}px`);
    bit.style.setProperty("--x1", `${dx}px`);
    bit.style.setProperty("--y1", `${dy}px`);
    bit.style.setProperty("--rot", `${(Math.random() * 360) | 0}deg`);
    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
    bit.style.transform = `translate3d(${originX}px, ${originY}px, 0) rotate(0deg) scale(1)`;
    container.appendChild(bit);
    requestAnimationFrame(() => requestAnimationFrame(() => bit.classList.add("fly")));
    setTimeout(() => bit.remove(), 700);
  }
}

function flyBubble(imgSrc, fromRect, toRect, container) {
  const bubble = document.createElement("div");
  bubble.className = "add-bubble";
  const startSize = Math.min(120, Math.max(fromRect.width, fromRect.height));
  const endSize = 22;
  const startX = fromRect.left + fromRect.width / 2 - startSize / 2;
  const startY = fromRect.top + fromRect.height / 2 - startSize / 2;
  bubble.style.width = `${startSize}px`;
  bubble.style.height = `${startSize}px`;
  bubble.style.left = `${startX}px`;
  bubble.style.top = `${startY}px`;
  bubble.style.transform = "translate3d(0,0,0) scale(1)";
  const img = document.createElement("img");
  img.src = imgSrc;
  img.alt = "";
  bubble.appendChild(img);
  container.appendChild(bubble);
  if (reduceMotion) { bubble.remove(); return; }
  const destX = toRect.left + toRect.width / 2 - (startX + startSize / 2);
  const destY = toRect.top + toRect.height / 2 - (startY + startSize / 2);
  const scale = endSize / startSize;
  requestAnimationFrame(() =>
    requestAnimationFrame(() => {
      bubble.style.transform = `translate3d(${destX}px, ${destY}px, 0) scale(${scale})`;
      bubble.classList.add("fly");
    })
  );
  setTimeout(() => bubble.remove(), 700);
}

const kaluToast = document.getElementById("kalu-toast");
let kaluToastTimer = null;
function showKaluToast(title, sub, ok = true) {
  if (!kaluToast) return;
  const t = kaluToast.querySelector("strong"),
    m = kaluToast.querySelector("small"),
    i = kaluToast.querySelector(".kalu-toast-icon");
  if (t && title) t.textContent = title;
  if (m && sub) m.textContent = sub;
  if (i) i.textContent = ok ? "✓" : "!";
  kaluToast.classList.add("show");
  clearTimeout(kaluToastTimer);
  kaluToastTimer = setTimeout(() => kaluToast.classList.remove("show"), 3000);
}

const pulseOrderButton = () => {
  if (!selectionButton) return;
  selectionButton.classList.remove("fab-pulse");
  void selectionButton.offsetWidth;
  selectionButton.classList.add("fab-pulse");
  setTimeout(() => selectionButton.classList.remove("fab-pulse"), 600);
};

function flashCheck(wrap) {
  if (!wrap || reduceMotion) return;
  const el = document.createElement("div");
  el.className = "add-flash";
  el.setAttribute("aria-hidden", "true");
  el.innerHTML = '<svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="46"></circle><path d="M28 52 L44 68 L74 34"></path></svg>';
  wrap.appendChild(el);
  setTimeout(() => el.remove(), 1050);
}

function addToOrder(card) {
  if (!card) return;
  const { name, code, image, desc } = card.dataset;
  const product = { name, code, image, desc };
  if (isSoldOut(code)) {
    showKaluToast("Producto agotado", "Por ahora no está disponible.", false);
    return;
  }
  if (isSelected(product)) {
    selectedProducts = selectedProducts.filter((item) => item.code !== code);
    saveSelection();
    updateSelection();
    showKaluToast("Quitado de Mi pedido", `${name} fue removido de tu selección.`);
    return;
  }
  const isRental = /^DF/.test(code);
  const wrap = card.querySelector(".image-wrap");
  const img = wrap && wrap.querySelector("img");
  const imgRect = (wrap || card).getBoundingClientRect();
  selectedProducts.push(product);
  saveSelection();
  updateSelection();
  showKaluToast(
    isRental ? "Disfraz agregado a Mi pedido" : "Agregado a Mi pedido",
    isRental ? "Los disfraces de alquiler pueden requerir depósito. Ábrelo abajo a la derecha." : "Toca 'Mi pedido' abajo a la derecha para pedir por WhatsApp."
  );
  flashCheck(wrap);
  spawnConfetti(imgRect.left + imgRect.width / 2, imgRect.top + imgRect.height / 2, document.body);
  const launch = () => {
    if (img && selectionButton) flyBubble(img.currentSrc || img.src, imgRect, selectionButton.getBoundingClientRect(), document.body);
    setTimeout(pulseOrderButton, reduceMotion ? 0 : 520);
  };
  reduceMotion ? launch() : setTimeout(launch, 320);
}

function focusCard(card) {
  if (!card) return;
  const rental = card.closest(".rental-group[data-rental-window]");
  if (rental) {
    const tab = document.querySelector(`.rental-window-tab[data-rental-target="${rental.dataset.rentalWindow}"]`);
    if (tab) tab.click();
  }
  card.hidden = false;
  card.setAttribute("aria-hidden", "false");
  setTimeout(() => {
    card.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "center" });
    card.classList.remove("card-spot");
    void card.offsetWidth;
    card.classList.add("card-spot");
    setTimeout(() => card.classList.remove("card-spot"), 1500);
  }, 150);
}

/* Reubica la lupa dentro de .image-wrap para dejar el botón de compra limpio y ancho */
document.querySelectorAll(".card").forEach((card) => {
  const wrap = card.querySelector(".image-wrap");
  const zoom = card.querySelector(".zoom-button");
  if (wrap && zoom && zoom.parentElement !== wrap) {
    wrap.appendChild(zoom);
  }
});

document.querySelectorAll(".card .mini-button").forEach((btn) =>
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    addToOrder(btn.closest(".card"));
  })
);

selectionButton?.addEventListener("click", () => {
  updateSelection();
  selectionModal?.showModal();
});
document.getElementById("close-selection")?.addEventListener("click", () => selectionModal?.close());
selectionModal?.addEventListener("click", (event) => {
  if (event.target === selectionModal) selectionModal.close();
});
selectionList?.addEventListener("click", (event) => {
  const removeButton = event.target.closest("[data-remove-code]");
  if (!removeButton) return;
  selectedProducts = selectedProducts.filter((product) => product.code !== removeButton.dataset.removeCode);
  saveSelection();
  updateSelection();
});
clearSelection?.addEventListener("click", () => {
  selectedProducts = [];
  saveSelection();
  updateSelection();
});
[selectionWhatsappPrincipal, selectionWhatsappSecundaria].forEach((link) => {
  link?.addEventListener("click", (event) => {
    if (!selectedProducts.length) event.preventDefault();
  });
});

updateSelection();

/* Menú de navegación */
(function () {
  const navToggle = document.getElementById("nav-toggle");
  const navLinks = document.getElementById("nav-links");
  if (!navToggle || !navLinks) return;
  const closeMobileMenu = () => {
    navLinks.classList.remove("open");
    navToggle.setAttribute("aria-expanded", "false");
  };
  navToggle.addEventListener("click", () => {
    const isOpen = navLinks.classList.toggle("open");
    navToggle.setAttribute("aria-expanded", String(isOpen));
  });
  navLinks.querySelectorAll("a").forEach((link) => link.addEventListener("click", closeMobileMenu));
  document.addEventListener("click", (event) => {
    if (!event.target.closest(".nav")) closeMobileMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") closeMobileMenu();
  });
})();

/* Buscador global de productos con miniaturas */
(function () {
  const input = document.getElementById("site-search-input");
  const box = document.getElementById("site-search-results");
  const wrap = document.getElementById("site-search");
  if (!input || !box || !wrap) return;
  const cards = Array.from(document.querySelectorAll(".card[data-kalu-product]"));
  const norm = (v) => String(v || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const productData = (card) => ({
    code: card.dataset.code || "",
    name: card.dataset.name || card.querySelector("h3")?.textContent || "",
    category: card.dataset.category || "Producto Kalú",
    image: card.dataset.image || card.querySelector("img")?.getAttribute("src") || "",
  });
  const render = () => {
    const q = norm(input.value.trim());
    if (q.length < 2) {
      box.hidden = true;
      box.innerHTML = "";
      return;
    }
    const terms = q.split(/\s+/).filter(Boolean);
    const matches = cards
      .map(productData)
      .filter((p) => {
        const hay = norm(`${p.name} ${p.code} ${p.category}`);
        return terms.every((t) => hay.includes(t));
      })
      .slice(0, 12);
    if (!matches.length) {
      box.innerHTML = '<div class="site-search-empty">No encontramos productos con esa búsqueda.</div>';
      box.hidden = false;
      return;
    }
    box.innerHTML = matches
      .map(
        (p) =>
          `<button class="site-search-result" type="button" data-search-code="${esc(p.code)}"><span class="site-search-thumb"><img src="${esc(p.image)}" alt="" loading="lazy"></span><span class="site-search-copy"><strong>${esc(p.name)}</strong><small>${esc(p.code)}</small><em>${esc(p.category)}</em></span></button>`
      )
      .join("");
    box.hidden = false;
  };
  input.addEventListener("input", render);
  input.addEventListener("focus", render);
  box.addEventListener("click", (e) => {
    const item = e.target.closest("[data-search-code]");
    if (!item) return;
    const card = cards.find((c) => c.dataset.code === item.dataset.searchCode);
    if (card) focusCard(card);
    box.hidden = true;
    input.value = "";
    input.blur();
  });
  document.addEventListener("click", (e) => {
    if (!wrap.contains(e.target)) box.hidden = true;
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      box.hidden = true;
      input.blur();
    }
  });
})();

/* Enlaces directos a #producto=CODIGO */
(function () {
  const openFromHash = () => {
    const match = location.hash.match(/^#producto=(.+)$/);
    if (!match) return;
    const code = decodeURIComponent(match[1]);
    const card = Array.from(document.querySelectorAll(".card[data-code]")).find((c) => c.dataset.code === code);
    if (!card) return;
    setTimeout(() => focusCard(card), 250);
    history.replaceState(null, "", location.pathname + location.search);
  };
  window.addEventListener("hashchange", openFromHash);
  window.addEventListener("load", openFromHash);
})();

loadStock();

/* Animación de saludo en el logo */
(function () {
  const logo = document.querySelector("[data-klogo]");
  if (!logo || reduceMotion) return;
  const pieces = Array.from(logo.querySelectorAll(".kl-l"));
  let busy = false;
  const wave = () => {
    if (busy) return;
    busy = true;
    pieces.forEach((el, i) =>
      el.animate(
        [{ transform: "translateY(0)" }, { transform: "translateY(-6%)" }, { transform: "translateY(0)" }],
        { duration: 650, delay: i * 70, easing: "cubic-bezier(.22,1,.36,1)" }
      )
    );
    setTimeout(() => { busy = false; }, 650 + pieces.length * 70);
  };
  logo.addEventListener("pointerenter", wave);
  logo.addEventListener("pointerdown", wave);
})();

/* Pantalla de carga ágil */
(function () {
  const loader = document.getElementById("kaluLoader");
  if (!loader) return;
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    document.body.classList.remove("kalu-loading");
    document.body.classList.add("kalu-ready");
    loader.classList.add("is-hidden");
    setTimeout(() => loader.remove(), 500);
  };
  if (document.readyState === "complete") finish();
  else window.addEventListener("load", finish, { once: true });
  setTimeout(finish, 2000);
})();

/* Botón Volver arriba */
(function () {
  const btn = document.getElementById("backTop");
  if (!btn) return;
  let ticking = false;
  const update = () => {
    ticking = false;
    btn.classList.toggle("is-visible", window.scrollY > 520);
  };
  addEventListener("scroll", () => {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(update);
    }
  }, { passive: true });
  update();
})();

/* Interacción con modelo 3D y video en Hero */
(function () {
  const stage = document.querySelector(".halloween-3d-stage");
  const model = document.querySelector(".halloween-3d-model");
  if (!stage || !model) return;
  let timer, dragging = false, startX = 0, lastX = 0, theta = 0, horizontalDrag = false, didDrag = false;
  const getTheta = () => {
    const orbit = (model.getAttribute("camera-orbit") || "0deg 82deg 105%").split(/\s+/);
    const raw = parseFloat(orbit[0]);
    return Number.isFinite(raw) ? raw : 0;
  };
  theta = getTheta();
  const setTheta = () => {
    model.setAttribute("camera-orbit", `${theta}deg 82deg 105%`);
  };
  stage.addEventListener("pointerdown", (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    dragging = true; horizontalDrag = false; didDrag = false; startX = lastX = e.clientX;
    stage._startY = e.clientY;
    stage.setPointerCapture?.(e.pointerId);
  });
  stage.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const dx = e.clientX - lastX;
    const totalX = e.clientX - startX;
    const totalY = e.clientY - (stage._startY ?? e.clientY);
    if (Math.abs(totalX) > 8 || Math.abs(totalY) > 8) didDrag = true;
    if (Math.abs(totalX) > 6) horizontalDrag = Math.abs(totalX) > Math.abs(totalY);
    if (horizontalDrag) {
      e.preventDefault();
      theta -= dx * 0.55;
      if (theta > 180) theta -= 360;
      if (theta < -180) theta += 360;
      setTheta();
    }
    lastX = e.clientX;
  });
  const endDrag = (e) => {
    dragging = false; horizontalDrag = false;
    try { stage.releasePointerCapture?.(e.pointerId); } catch (_) {}
  };
  stage.addEventListener("pointerup", endDrag);
  stage.addEventListener("pointercancel", endDrag);

  const pop = () => {
    stage.classList.remove("is-popping");
    void stage.offsetWidth;
    stage.classList.add("is-popping");
    clearTimeout(timer);
    timer = setTimeout(() => stage.classList.remove("is-popping"), 760);
  };
  const video = document.getElementById("cat-video");
  let videoReady = false;
  const showModel = () => {
    stage.classList.remove("is-video");
    try { video?.pause(); } catch (_) {}
  };
  if (video) {
    video.loop = true;
    video.addEventListener("canplay", () => { videoReady = true; }, { once: true });
    video.addEventListener("error", () => { videoReady = false; showModel(); });
    const loadVideo = () => {
      if (!video.getAttribute("src") && video.dataset.src) {
        video.src = video.dataset.src;
        video.load();
      }
    };
    const idle = window.requestIdleCallback || ((fn) => setTimeout(fn, 1500));
    if (document.readyState === "complete") idle(loadVideo);
    else addEventListener("load", () => idle(loadVideo), { once: true });
  }
  const showVideo = () => {
    if (!video || !videoReady) return false;
    video.currentTime = 0;
    const pr = video.play();
    stage.classList.add("is-video");
    if (pr && pr.catch) pr.catch(showModel);
    return true;
  };
  const toggle = () => {
    if (stage.classList.contains("is-video")) { showModel(); pop(); return; }
    if (!showVideo()) pop();
  };
  stage.addEventListener("click", () => {
    if (didDrag) { didDrag = false; return; }
    toggle();
  });
})();

/* Pestañas de Alquiler + Filtros de Categoría + Paginación E-commerce */
(function () {
  const INITIAL_VISIBLE = 12;
  const STEP_VISIBLE = 16;
  const rentalTabs = Array.from(document.querySelectorAll(".rental-window-tab"));
  const rentalGroups = Array.from(document.querySelectorAll("#alquiler .rental-group"));

  const setupGridPagination = (group, matchingCards) => {
    const grid = group.querySelector(".grid");
    if (!grid) return;
    let wrap = group.querySelector(".kalu-load-more-wrap");
    if (!wrap) {
      wrap = document.createElement("div");
      wrap.className = "kalu-load-more-wrap";
      grid.insertAdjacentElement("afterend", wrap);
    }
    let limit = INITIAL_VISIBLE;
    const renderLimit = () => {
      matchingCards.forEach((card, idx) => {
        const show = idx < limit;
        card.hidden = !show;
        card.setAttribute("aria-hidden", String(!show));
      });
      const remaining = matchingCards.length - limit;
      if (remaining > 0) {
        wrap.innerHTML = `<button type="button" class="kalu-load-more">Ver más productos (${remaining} restantes) ↓</button>`;
        wrap.querySelector("button").addEventListener("click", () => {
          limit += STEP_VISIBLE;
          renderLimit();
        });
      } else {
        wrap.innerHTML = "";
      }
    };
    renderLimit();
  };

  function applyFilter(button) {
    if (!button) return;
    const nav = button.closest(".section-filter");
    if (!nav) return;
    const value = button.dataset.filterValue || "";
    const attr = nav.dataset.filterAttr || "data-category";
    const group = nav.closest(".rental-group") || nav.closest("section");
    if (!group) return;

    nav.querySelectorAll(".section-filter-pill").forEach((b) => {
      const active = b === button;
      b.classList.toggle("is-active", active);
      b.setAttribute("aria-selected", String(active));
    });

    const cards = Array.from(group.querySelectorAll("article.card[data-code]"));
    const matching = [];
    cards.forEach((card) => {
      const cardValue = (card.getAttribute(attr) || "").trim();
      const show = !value || cardValue === value;
      if (show) matching.push(card);
      else {
        card.hidden = true;
        card.setAttribute("aria-hidden", "true");
      }
    });

    let status = nav.querySelector(".section-filter-status");
    if (!status) {
      status = document.createElement("span");
      status.className = "section-filter-status";
      status.setAttribute("aria-live", "polite");
      nav.appendChild(status);
    }
    status.textContent = `${matching.length} ${matching.length === 1 ? "producto" : "productos"}`;

    setupGridPagination(group, matching);
  }

  const activateRental = (id) => {
    rentalTabs.forEach((tab) => {
      const on = tab.dataset.rentalTarget === id;
      tab.classList.toggle("is-active", on);
      tab.setAttribute("aria-selected", String(on));
      tab.tabIndex = on ? 0 : -1;
    });
    rentalGroups.forEach((group) => {
      const on = group.dataset.rentalWindow === id;
      group.classList.toggle("catalog-window-active", on);
      group.classList.toggle("catalog-window-hidden", !on);
      group.hidden = !on;
    });
    const activeGroup = rentalGroups.find((group) => group.dataset.rentalWindow === id);
    if (activeGroup) {
      const first = activeGroup.querySelector(".section-filter-pill");
      if (first) applyFilter(first);
    }
  };

  rentalTabs.forEach((tab) => {
    tab.addEventListener("click", () => activateRental(tab.dataset.rentalTarget));
  });

  const rentalIds = new Set(rentalTabs.map((tab) => tab.dataset.rentalTarget));
  const goRental = (id, smooth = true) => {
    activateRental(id);
    const bar = document.querySelector("#alquiler .rental-window-tabs");
    if (!bar) return;
    const nav = document.querySelector(".nav");
    const offset = (nav ? nav.getBoundingClientRect().height : 68) + 12;
    window.scrollTo({
      top: bar.getBoundingClientRect().top + window.scrollY - offset,
      behavior: smooth ? "smooth" : "auto",
    });
  };

  document.addEventListener("click", (event) => {
    const link = event.target.closest('a[href^="#alquiler-"]');
    if (!link) return;
    const id = link.getAttribute("href").slice(1);
    if (!rentalIds.has(id)) return;
    event.preventDefault();
    goRental(id);
    history.replaceState(null, "", "#" + id);
  });

  document.querySelectorAll(".section-filter-list").forEach((list) => {
    list.addEventListener("click", (e) => {
      const button = e.target.closest(".section-filter-pill");
      if (button && list.contains(button)) applyFilter(button);
    });
  });

  if (rentalTabs.length) activateRental(rentalTabs[0]?.dataset.rentalTarget || "alquiler-nino");
  document.querySelectorAll(".section-filter").forEach((nav) => {
    const first = nav.querySelector(".section-filter-pill");
    if (first) applyFilter(first);
  });

  /* Si alguna sección de catálogo no tiene barra de filtros (ej. Típicos de baile), también aplica paginación */
  document.querySelectorAll("section").forEach((sec) => {
    if (sec.querySelector(".section-filter") || sec.id === "alquiler") return;
    const cards = Array.from(sec.querySelectorAll(":scope .grid > article.card[data-code]"));
    if (cards.length > INITIAL_VISIBLE) setupGridPagination(sec, cards);
  });
})();

/* Ficha de Producto Quick-Shop (Siempre muestra botones de compra al tocar foto o lupa) */
(function () {
  const dialog = document.getElementById("kalu-product-dialog");
  if (!dialog) return;
  const image = document.getElementById("kalu-product-image"),
    title = document.getElementById("kalu-product-title"),
    code = document.getElementById("kalu-product-code"),
    desc = document.getElementById("kalu-product-description"),
    cat = document.getElementById("kalu-product-category"),
    wa = document.getElementById("kalu-product-wa"),
    add = document.getElementById("kalu-product-add");

  let activeCard = null;
  const escText = (v) => String(v || "").trim();

  const productFromCard = (card) => ({
    name: escText(card.dataset.name || card.querySelector("h3")?.textContent),
    code: escText(card.dataset.code || card.querySelector(".code")?.textContent),
    image: escText(card.dataset.image || card.querySelector("img")?.getAttribute("src")),
    desc: escText(card.dataset.desc || card.querySelector("p")?.textContent),
    category: escText(card.dataset.category || "Producto Kalú"),
  });

  const syncModalAddButton = (pCode) => {
    if (!add) return;
    const added = isSelected({ code: pCode });
    add.textContent = added ? "✓ En mi pedido (Toca para quitar)" : "＋ Agregar a mi selección";
  };

  const openProduct = (card) => {
    const p = productFromCard(card);
    activeCard = card;
    dialog.classList.remove("is-quick");
    if (image) { image.src = p.image; image.alt = p.name; }
    if (title) title.textContent = p.name;
    if (code) code.textContent = p.code;
    if (desc) desc.textContent = p.desc || "Consulta disponibilidad y precio.";
    if (cat) cat.textContent = p.category || "Producto Kalú";

    if (wa) {
      const msg = `Hola Kalú, quiero consultar por ${p.name} (${p.code}).`;
      const numero = /^DF|^TB/.test(p.code) ? SEDES.secundaria.numero : SEDES.principal.numero;
      wa.href = waLink(numero, msg);
    }

    syncModalAddButton(p.code);

    const mediaEl = dialog.querySelector(".kalu-product-media");
    if (mediaEl) mediaEl.scrollTop = 0;
    if (typeof dialog.showModal === "function") dialog.showModal();
    else dialog.setAttribute("open", "");
  };

  document.getElementById("kalu-product-close")?.addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });

  document.querySelectorAll(".card[data-kalu-product]").forEach((card) => {
    card.addEventListener("click", (e) => {
      if (e.target.closest(".mini-button, a, input, select, textarea")) return;
      openProduct(card);
    });
    card.querySelector(".zoom-button")?.addEventListener("click", (e) => {
      e.stopPropagation();
      openProduct(card);
    });
  });

  add?.addEventListener("click", () => {
    if (!activeCard) return;
    addToOrder(activeCard);
    syncModalAddButton(activeCard.dataset.code);
  });
})();
/* Catálogo unificado de compra y alquiler */
(function(){
  const shop=document.getElementById("shop-catalog");
  const grid=document.getElementById("shop-grid");
  if(!shop||!grid)return;
  const cards=Array.from(document.querySelectorAll(".card[data-kalu-product]"));
  const categoryNames={"alquiler-nino":"Disfraces para niño","alquiler-nina":"Disfraces para niña","alquiler-adulto":"Disfraces para adulto","alquiler-bebe":"Disfraces para bebé"};
  const extraValue=(card)=>card.dataset.material||card.dataset.category||card.dataset.gender||"";
  cards.forEach(card=>{
    let kind="buy",category="Accesorios",detail=extraValue(card),audience="";
    if(card.classList.contains("mask-card")){category="Máscaras y antifaces";detail=card.dataset.material||card.dataset.category||"";}
    else if(card.classList.contains("rental-card")){kind="rent";const group=card.closest(".rental-group");const groupId=card.closest(".grid")?.id||group?.id;category=categoryNames[groupId]||"Disfraces";detail=card.dataset.category||"";audience=({"alquiler-bebe":"baby","alquiler-nino":"boy","alquiler-nina":"girl","alquiler-adulto":"adult"})[groupId]||"";}
    else if(card.classList.contains("folk-card")){kind="rent";category="Trajes típicos";detail=card.dataset.gender||card.dataset.category||"";audience="folk";}
    card.dataset.shopKind=kind;card.dataset.shopCategory=category;card.dataset.shopDetail=detail;card.dataset.shopAudience=audience;
    card.hidden=false;card.setAttribute("aria-hidden","false");const imageWrap=card.querySelector(".image-wrap");if(imageWrap&&!imageWrap.querySelector(".shop-product-kind")){const badge=document.createElement("span");badge.className="shop-product-kind";badge.textContent=kind==="buy"?"Compra":audience==="folk"?"Alquiler · Típicos":`Alquiler · ${({baby:"Bebé",boy:"Niño",girl:"Niña",adult:"Adulto"})[audience]||"Disfraces"}`;imageWrap.appendChild(badge);}grid.appendChild(card);
  });
  document.body.classList.add("unified-store-ready");
  const kindButtons=Array.from(shop.querySelectorAll("[data-shop-kind]"));
  const categorySelect=document.getElementById("shop-category-filter");
  const detailSelect=document.getElementById("shop-detail-filter");
  const audiencePanel=document.getElementById("shop-audience-filters");
  const audienceButtons=Array.from(shop.querySelectorAll("[data-shop-audience]"));
  const status=document.getElementById("shop-results-status");
  const moreWrap=document.getElementById("shop-more-wrap");
  const empty=document.getElementById("shop-empty");
  const search=document.getElementById("site-search-input");
  const normalize=value=>String(value||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim();
  let activeKind="all",activeAudience="all",limit=24;
  const unique=values=>Array.from(new Set(values.filter(Boolean))).sort((a,b)=>a.localeCompare(b,"es"));
  const audienceForCategory={"Disfraces para bebé":"baby","Disfraces para niño":"boy","Disfraces para niña":"girl","Disfraces para adulto":"adult","Trajes típicos":"folk"};
  const syncAudience=()=>{audiencePanel.hidden=activeKind!=="rent";audienceButtons.forEach(button=>{const active=button.dataset.shopAudience===activeAudience;button.classList.toggle("is-active",active);button.setAttribute("aria-pressed",String(active));});};
  const kindMatches=card=>(activeKind==="all"||card.dataset.shopKind===activeKind)&&(activeAudience==="all"||card.dataset.shopAudience===activeAudience);
  const rebuildCategories=()=>{
    const prior=categorySelect.value;
    const values=unique(cards.filter(kindMatches).map(card=>card.dataset.shopCategory));
    categorySelect.innerHTML='<option value="">Todas las categorías</option>'+values.map(value=>`<option value="${value.replace(/&/g,"&amp;").replace(/"/g,"&quot;")}">${value}</option>`).join("");
    if(values.includes(prior))categorySelect.value=prior;
    rebuildDetails();
  };
  const rebuildDetails=()=>{
    const prior=detailSelect.value;
    const values=unique(cards.filter(card=>kindMatches(card)&&(!categorySelect.value||card.dataset.shopCategory===categorySelect.value)).map(card=>card.dataset.shopDetail));
    detailSelect.innerHTML='<option value="">Todos los tipos</option>'+values.map(value=>`<option value="${value.replace(/&/g,"&amp;").replace(/"/g,"&quot;")}">${value}</option>`).join("");
    if(values.includes(prior))detailSelect.value=prior;
  };
  const render=()=>{
    const terms=normalize(search?.value).split(/\s+/).filter(Boolean);
    const selectedCategory=categorySelect.value,selectedDetail=detailSelect.value;
    const matches=cards.filter(card=>{
      const text=normalize(`${card.dataset.name} ${card.dataset.code} ${card.dataset.desc} ${card.dataset.shopCategory} ${card.dataset.shopDetail}`);
      return kindMatches(card)&&(!selectedCategory||card.dataset.shopCategory===selectedCategory)&&(!selectedDetail||card.dataset.shopDetail===selectedDetail)&&terms.every(term=>text.includes(term));
    });
    const showCount=Math.min(limit,matches.length);
    cards.forEach(card=>{const visible=matches.slice(0,showCount).includes(card);card.hidden=!visible;card.setAttribute("aria-hidden",String(!visible));});
    status.textContent=matches.length?`Mostrando ${showCount} de ${matches.length} ${matches.length===1?"producto":"productos"}`:"";
    empty.hidden=matches.length!==0;
    moreWrap.innerHTML=matches.length>limit?'<button class="shop-load-more" type="button">Ver más productos</button>':'';
    const more=moreWrap.querySelector("button");
    if(more)more.addEventListener("click",()=>{limit+=24;render();});
  };
  kindButtons.forEach(button=>button.addEventListener("click",()=>{
    activeKind=button.dataset.shopKind;activeAudience="all";limit=24;
    kindButtons.forEach(item=>{const active=item===button;item.classList.toggle("is-active",active);item.setAttribute("aria-pressed",String(active));});
    categorySelect.value="";detailSelect.value="";syncAudience();rebuildCategories();render();
  }));
  categorySelect.addEventListener("change",()=>{limit=24;activeAudience=activeKind==="rent"?(audienceForCategory[categorySelect.value]||"all"):"all";syncAudience();rebuildDetails();render();});
  detailSelect.addEventListener("change",()=>{limit=24;render();});
  search?.addEventListener("input",()=>{limit=24;render();});
  search?.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();shop.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});}});
  document.getElementById("shop-clear-filters")?.addEventListener("click",()=>{
    activeKind="all";activeAudience="all";limit=24;if(search)search.value="";categorySelect.value="";detailSelect.value="";
    kindButtons.forEach(button=>{const active=button.dataset.shopKind==="all";button.classList.toggle("is-active",active);button.setAttribute("aria-pressed",String(active));});
    syncAudience();rebuildCategories();render();
  });
  audienceButtons.forEach(button=>button.addEventListener("click",()=>{activeKind="rent";activeAudience=button.dataset.shopAudience;limit=24;kindButtons.forEach(item=>{const active=item.dataset.shopKind==="rent";item.classList.toggle("is-active",active);item.setAttribute("aria-pressed",String(active));});categorySelect.value="";detailSelect.value="";syncAudience();rebuildCategories();render();}));
  const linkFilters={"#venta":{kind:"buy"},"#alquiler":{kind:"rent"},"#alquiler-nino":{kind:"rent",category:"Disfraces para niño",audience:"boy"},"#alquiler-nina":{kind:"rent",category:"Disfraces para niña",audience:"girl"},"#alquiler-adulto":{kind:"rent",category:"Disfraces para adulto",audience:"adult"},"#alquiler-bebe":{kind:"rent",category:"Disfraces para bebé",audience:"baby"},"#tipicos-linea":{kind:"rent",category:"Trajes típicos",audience:"folk"},"#tipicos-baile":{kind:"rent",category:"Trajes típicos",audience:"folk"},"#mascaras":{kind:"buy",category:"Máscaras y antifaces"},"#accesorios":{kind:"buy",category:"Accesorios"}};
  document.addEventListener("click",event=>{
    const link=event.target.closest('a[href^="#"]');const filter=link&&linkFilters[link.getAttribute("href")];if(!filter)return;
    event.preventDefault();activeKind=filter.kind;activeAudience=filter.audience||"all";limit=24;
    kindButtons.forEach(button=>{const active=button.dataset.shopKind===activeKind;button.classList.toggle("is-active",active);button.setAttribute("aria-pressed",String(active));});
    categorySelect.value="";detailSelect.value="";syncAudience();rebuildCategories();
    if(filter.category)categorySelect.value=filter.category;
    rebuildDetails();render();
    shop.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});
  });
  document.getElementById("site-search-results")?.addEventListener("click",event=>{
    const item=event.target.closest("[data-search-code]");if(!item)return;
    const card=cards.find(product=>product.dataset.code===item.dataset.searchCode);if(!card)return;
    activeKind=card.dataset.shopKind;activeAudience=card.dataset.shopAudience||"all";limit=24;
    kindButtons.forEach(button=>{const active=button.dataset.shopKind===activeKind;button.classList.toggle("is-active",active);button.setAttribute("aria-pressed",String(active));});
    categorySelect.value="";detailSelect.value="";syncAudience();rebuildCategories();categorySelect.value=card.dataset.shopCategory;rebuildDetails();render();
  });  syncAudience();rebuildCategories();render();
})();